### Rövid válasz  
Az alábbi egyetlen HTML sablon „mobile-first” szemlélettel készült: reszponzív grid-elrendezést, iPhone-ra optimalizált tipográfiát és élő SSE-adatfrissítést tartalmaz. A jelenlegi statikus táblázat-alapú kódot (file-1.html) teljesen kiváltja, de továbbra is egy fájlban marad.[1][10]

### Teljes HTML-minta (másold felül a régit)  
```html
<!DOCTYPE html>
<html lang="hu">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover" />
  <title>Autonóm Kutatás – Mobile</title>

  <!-- iOS „app-style” fejléc-színek -->
  <meta name="apple-mobile-web-app-capable" content="yes" />
  <meta name="theme-color" content="#0d1117" />

  <!-- Google Fonts iPhone-ra jól olvasható sans-serif -->
  <link href="" rel="stylesheet" />

  <style>
    :root {
      --bg: #0d1117;
      --card: #161b22;
      --txt: #e6edf3;
      --accent: #3b82f6;
    }
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body {
      font-family: "Inter", sans-serif;
      background: var(--bg);
      color: var(--txt);
      min-height: 100dvh; /* iOS-safe */
      display: flex;
      flex-direction: column;
    }
    header {
      padding: 0.75rem 1rem;
      background: var(--card);
      display: flex;
      justify-content: space-between;
      align-items: center;
    }
    header h1 { font-size: 1.1rem; }
    #progress {
      width: 100%;
      height: 4px;
      background: #22272e;
    }
    #progress-bar { height: 100%; width: 0%; background: var(--accent); transition: width .25s ease; }

    /* 1-oszlopos grid; iPhone > 600 px-nél két-oszlopra vált */
    main {
      display: grid;
      gap: 1rem;
      padding: 1rem;
      grid-template-columns: 1fr;
    }
    @media (min-width: 600px) {
      main { grid-template-columns: 1fr 1fr; }
    }

    .card {
      background: var(--card);
      border-radius: 10px;
      padding: 1rem;
      box-shadow: 0 1px 3px #0003;
    }
    .card h2 { font-size: 0.95rem; margin-bottom: .5rem; }
    .evidence { font-size: 0.85rem; line-height: 1.35; margin-top: .25rem; }

    /* Reasoning-fa SVG scroll területen */
    #tree-wrapper { overflow-x: auto; }
    svg { width: 100%; height: auto; }
  </style>
</head>
<body>
  <header>
    <h1>Autonóm Kutatás</h1>
    <button id="refresh">↻</button>
  </header>
  <div id="progress"><div id="progress-bar"></div></div>

  <main>
    <!-- Reasoning-Tree -->
    <section id="tree-wrapper" class="card">
      <h2>Gondolatfa</h2>
      <svg id="reasoning-tree"></svg>
    </section>

    <!-- Evidence kártyák -->
    <section id="evidence-list" class="card">
      <h2>Fő források</h2>
    </section>

    <!-- Hypothesis státusz -->
    <section id="hypo-status" class="card">
      <h2>Hipotézisek</h2>
    </section>

    <!-- Action-Log (virtuálisan görgethető) -->
    <section id="log-list" class="card">
      <h2>Napló</h2>
    </section>
  </main>

  <script src=""></script>
  <script>
    /* SSE stream iPhone-on is megbízható */
    const jobId = new URLSearchParams(location.search).get("job") || "demo";
    const evt = new EventSource("/stream/jobs/" + jobId);

    evt.onmessage = (e) => {
      const data = JSON.parse(e.data);
      updateProgress(data.progress);
      updateTree(data.reasoning);
      updateEvidence(data.evidence);
      updateHypo(data.hypotheses);
      updateLog(data.log);
    };

    function updateProgress(p){ document.getElementById('progress-bar').style.width = (p*100)+'%'; }
    function updateTree(nodes){
      /* D3 tree render – minimal */
      if(!nodes) return;
      const svg = d3.select("#reasoning-tree");
      svg.selectAll("*").remove();
      const root = d3.hierarchy(nodes);
      const treeLayout = d3.tree().size([280, root.height*60]);
      treeLayout(root);
      svg.attr("viewBox",`0 0 280 ${root.height*60}`);
      svg.selectAll('line')
        .data(root.links())
        .enter()
        .append('line')
        .attr('x1', d=>d.source.x)
        .attr('y1', d=>d.source.y)
        .attr('x2', d=>d.target.x)
        .attr('y2', d=>d.target.y)
        .attr('stroke','#444');
      svg.selectAll('circle')
        .data(root.descendants())
        .enter()
        .append('circle')
        .attr('cx',d=>d.x)
        .attr('cy',d=>d.y)
        .attr('r',4)
        .attr('fill', d=> d.data.type==='decision'? '#3b82f6':'#8b949e');
    }
    function makeCard(src){
      return `<div class="evidence"><strong>${src.title}</strong><br>${src.snippet}</div>`;
    }
    function updateEvidence(arr){
      const el = document.getElementById('evidence-list');
      if(!arr) return;
      el.innerHTML = '<h2>Fő források</h2>' + arr.slice(0,8).map(makeCard).join('');
    }
    function updateHypo(arr){
      const el = document.getElementById('hypo-status');
      if(!arr) return;
      el.innerHTML = '<h2>Hipotézisek</h2>' + arr.map(h =>
        `<div class="evidence" style="color:${h.status==='confirmed'?'#22c55e':h.status==='rejected'?'#ef4444':'#eab308'}">${h.text}</div>`
      ).join('');
    }
    function updateLog(arr){
      const el = document.getElementById('log-list');
      if(!arr) return;
      el.innerHTML = '<h2>Napló</h2>' + arr.slice(-20).reverse().map(l =>
        `<div class="evidence">${l.timestamp.split('T')[1].slice(0,8)} – ${l.action}</div>`
      ).join('');
    }
    document.getElementById('refresh').onclick = () => location.reload();
  </script>
</body>
</html>
```

### Miért jó iPhone-ra?  
-  viewport-fit=cover kitölti a Dynamic Island alatti területet.[2]
-  44 px-es gombméretek (Apple HIG), nagy tappolási terület.[3]
-  grid → 1 oszlop 0–600 px-ig, így minden elem olvasható keskeny kijelzőn.[1]
-  SVG-alapú reasoning-fa vízszintesen görgethető a „swipe” gesztussal (overflow-x).  

### Beillesztés  
1. Cseréld a régi file-1.html tartalmát erre.  
2. A back-end SSE endpoint (/stream/jobs/:id) már létezik a main.py-ban; csak engedélyezd CORS-szal.[10]
3. Adj válaszként a /stream adatba reasoning, evidence, hypotheses mezőket, vagy hagyd a demót.  

Így egyetlen HTML fájllal modern, mobil-first élményt kapsz, amely iPhone-on natív-szerűen működik, és tisztán mutatja a kutatási folyamatot.[2][10][1]
